            new("GetBucketVersioning", OperationStatus.Partial, new[] { "Azure: Container metadata (per-bucket toggle); reflects stored PutBucketVersioning intent", "Diff: GET returns the per-bucket toggle persisted by PutBucketVersioning. Azure Blob versioning itself is account-scoped: actual version retention requires account-level versioning enabled out-of-band by the operator.", "Diff: MFADelete is never reported (not supported)." }),
